  insAnalysingN: { en: "Game {a} of {b}. Each game is looked at once, then remembered.", pa: "{b} ਵਿੱਚੋਂ ਖੇਡ {a}। ਹਰ ਖੇਡ ਇੱਕ ਵਾਰ ਵੇਖੀ ਜਾਂਦੀ ਹੈ, ਫਿਰ ਯਾਦ ਰੱਖੀ ਜਾਂਦੀ ਹੈ।" },
  insFew: { en: "Play a few more games against the bots or a friend, and your patterns will show here.", pa: "ਬੋਟਾਂ ਜਾਂ ਕਿਸੇ ਦੋਸਤ ਨਾਲ ਕੁਝ ਹੋਰ ਖੇਡਾਂ ਖੇਡੋ, ਫਿਰ ਇੱਥੇ ਤੁਹਾਡੀ ਖੇਡ ਦੇ ਨਮੂਨੇ ਦਿਸਣਗੇ।" },
  insWeak: { en: "You lose the most points in the {weak}: {a}% accuracy, against {b}% in the {strong}.", pa: "ਤੁਸੀਂ ਸਭ ਤੋਂ ਵੱਧ ਅੰਕ {weak} ਵਿੱਚ ਗੁਆਉਂਦੇ ਹੋ: ਸ਼ੁੱਧਤਾ {a}%, ਜਦੋਂ ਕਿ {strong} ਵਿੱਚ {b}%।" },
  insEven: { en: "Your play is even: no part of the game is much weaker than the others. Keep it up!", pa: "ਤੁਹਾਡੀ ਖੇਡ ਹਰ ਹਿੱਸੇ ਵਿੱਚ ਇੱਕੋ ਜਿਹੀ ਹੈ: ਕੋਈ ਹਿੱਸਾ ਬਾਕੀਆਂ ਨਾਲੋਂ ਬਹੁਤ ਕਮਜ਼ੋਰ ਨਹੀਂ। ਇਵੇਂ ਹੀ ਖੇਡਦੇ ਰਹੋ!" },
  insRush_fast: { en: "And when you move in under 5 seconds, your accuracy drops to {a}%.", pa: "ਅਤੇ ੫ ਸਕਿੰਟ ਤੋਂ ਘੱਟ ਸੋਚ ਕੇ ਚੱਲੀ ਚਾਲ ਦੀ ਸ਼ੁੱਧਤਾ {a}% ਰਹਿ ਜਾਂਦੀ ਹੈ।" },
  insRush_mid: { en: "And when you think for 5 to 20 seconds, your accuracy drops to {a}%.", pa: "ਅਤੇ ੫ ਤੋਂ ੨੦ ਸਕਿੰਟ ਸੋਚ ਕੇ ਚੱਲੀ ਚਾਲ ਦੀ ਸ਼ੁੱਧਤਾ {a}% ਰਹਿ ਜਾਂਦੀ ਹੈ।" },
  insRush_slow: { en: "And when you think for over 20 seconds, your accuracy drops to {a}%.", pa: "ਅਤੇ ੨੦ ਸਕਿੰਟ ਤੋਂ ਵੱਧ ਸੋਚ ਕੇ ਚੱਲੀ ਚਾਲ ਦੀ ਸ਼ੁੱਧਤਾ {a}% ਰਹਿ ਜਾਂਦੀ ਹੈ।" },
  insSlowDown: { en: "Slow down when it matters.", pa: "ਅਹਿਮ ਮੌਕੇ 'ਤੇ ਕਾਹਲੀ ਨਾ ਕਰੋ।" },
  insPractise: { en: "Practise next", pa: "ਅਗਲਾ ਅਭਿਆਸ" },
  insOpenings: { en: "Openings", pa: "ਸ਼ੁਰੂਆਤਾਂ" }, insPhases: { en: "Game phases", pa: "ਖੇਡ ਦੇ ਹਿੱਸੇ" }, insTime: { en: "Thinking time", pa: "ਸੋਚਣ ਦਾ ਸਮਾਂ" },
  insPh_opening: { en: "Opening", pa: "ਸ਼ੁਰੂਆਤ" }, insPh_middlegame: { en: "Middlegame", pa: "ਵਿਚਕਾਰਲੀ ਖੇਡ" }, insPh_endgame: { en: "Endgame", pa: "ਅੰਤਲੀ ਖੇਡ" },
  insBand_fast: { en: "Under 5 s", pa: "੫ ਸਕਿੰਟ ਤੋਂ ਘੱਟ" }, insBand_mid: { en: "5–20 s", pa: "੫–੨੦ ਸਕਿੰਟ" }, insBand_slow: { en: "Over 20 s", pa: "੨੦ ਸਕਿੰਟ ਤੋਂ ਵੱਧ" },
  insShare: { en: "{n}% of moves", pa: "ਚਾਲਾਂ ਵਿੱਚੋਂ {n}%" },
  insNoOpenings: { en: "No named openings yet.", pa: "ਅਜੇ ਕਿਸੇ ਸ਼ੁਰੂਆਤ ਦਾ ਨਾਂ ਨਹੀਂ ਮਿਲਿਆ।" },
  insTooFew: { en: "Not enough moves yet", pa: "ਅਜੇ ਕਾਫ਼ੀ ਚਾਲਾਂ ਨਹੀਂ" },
  insTimeNone: { en: "Thinking time is recorded from now on. Play a few more games to see it.", pa: "ਸੋਚਣ ਦਾ ਸਮਾਂ ਹੁਣ ਤੋਂ ਦਰਜ ਹੁੰਦਾ ਹੈ। ਇਹ ਵੇਖਣ ਲਈ ਕੁਝ ਹੋਰ ਖੇਡਾਂ ਖੇਡੋ।" },
  insFromReview: { en: "Your insights from all your games", pa: "ਤੁਹਾਡੀਆਂ ਸਾਰੀਆਂ ਖੇਡਾਂ ਦੀ ਝਲਕ" },
  // game settings (DECISIONS #115, option B)
  gsGroup: { en: "Board", pa: "ਬੋਰਡ" }, gsMenu: { en: "Game settings", pa: "ਖੇਡ ਦੀਆਂ ਸੈਟਿੰਗਾਂ" }, gsInGame: { en: "During this game", pa: "ਇਸ ਖੇਡ ਦੌਰਾਨ" },
  gsConfirmLabel: { en: "Confirm each move", pa: "ਹਰ ਚਾਲ ਪੱਕੀ ਕਰੋ" },
