export type UIKey = keyof typeof UI;

export const lang = (): Lang => store.get().lang;
export const t = (k: UIKey): string => UI[k][lang()];
export const tx = (x: Text): string => x[lang()];

const GURMUKHI_DIGITS = "੦੧੨੩੪੫੬੭੮੯";
/** Numbers in Gurmukhi prose use Gurmukhi numerals (house rule from the book projects). */
export const num = (n: number | string): string =>
  lang() === "pa" ? String(n).replace(/\d/g, d => GURMUKHI_DIGITS[+d]) : String(n);
/** A large count with separators: 372,816 in English, ੩,੭੨,੮੧੬ in Punjabi (Indian grouping). */
export const count = (n: number): string => num(n.toLocaleString(lang() === "pa" ? "en-IN" : "en-GB"));
